608	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
609	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
610	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
611	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
612	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
613	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
614	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
615	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
616		handoverID = clean(handoverID)
617		itemID = clean(itemID)
618		operator = clean(operator)
619		reason = clean(reason)
620		trackingNote = clean(trackingNote)
621		nextFollowOwner = clean(nextFollowOwner)
622	
623		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
624			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
625		}
626		if err := requireNonEmpty("操作人", operator); err != nil {
627			return Handover{}, err
628		}
629	
630		var result Handover
631		err := svc.store.mutate(func(d *Data) error {
632			h, _ := findHandover(d, handoverID)
633			if h == nil {
634				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
635			}
636			e, _ := findEntry(h, itemID)
637			if e == nil {
638				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
639			}
640			if e.Status.Received() {
641				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
642					ErrHandoverState, e.ItemID, e.Status.Label())
643			}
644			if e.Status == EntryReturned {
645				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
646				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
647				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
648				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
649					ErrHandoverState, e.ItemID, h.ID)
650			}
651			switch action {
652			case ActionReturn:
653				if err := requireNonEmpty("退回原因", reason); err != nil {
654					return err
655				}
656			case ActionTrack:
657				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
658					return err
659				}
660				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
661					return err
662				}
663			}
664	
665			now := svc.now()
666			switch action {
667			case ActionConfirm:
668				e.Status = EntryConfirmed
669			case ActionTrack:
670				e.Status = EntryTracking
671				e.TrackingNote = trackingNote
672				e.FollowOwner = nextFollowOwner
673			case ActionReturn:
674				e.Status = EntryReturned
675				e.Rounds = append(e.Rounds, ReturnRound{
676					Seq:            len(e.Rounds) + 1,
677					ReturnedAt:     now,
678					ReturnOperator: operator,
679					Reason:         reason,
680				})
681			}
682			e.Operator = operator
683			e.ProcessedAt = &now
684	
685			if action != ActionReturn {
686				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
687				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
688					it.CurrentShiftID = h.ToShiftID
689					if !contains(it.ShiftIDs, h.ToShiftID) {
690						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
691					}
692					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
693					if action == ActionTrack {
694						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
695						it.FollowOwner = nextFollowOwner
696					}
697					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
698				}
699			}
700	
701			if h.Completed() {
702				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
703				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
704				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
705				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
706				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
707				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
708				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
709				// 项无法再处理，完成时间不会被改写。
710				h.CompletedAt = &now
711			}
712			result = *h
713			return nil
714		})
715		return result, err
716	}
717	
718	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
719	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
720	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
721	
722	func contains(xs []string, x string) bool {
723		for _, v := range xs {
724			if v == x {
725				return true
726			}
727		}
728		return false
729	}
730	
731	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
732	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
733	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
734	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
735	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
736	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
737	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
738		handoverID = clean(handoverID)
739		itemID = clean(itemID)
740		operator = clean(operator)
741		supplement = clean(supplement)
742		if err := requireNonEmpty("操作人", operator); err != nil {
743			return Handover{}, err
744		}
745		if err := requireNonEmpty("补充说明", supplement); err != nil {
746			return Handover{}, err
747		}
748	
749		var result Handover
750		err := svc.store.mutate(func(d *Data) error {
751			h, _ := findHandover(d, handoverID)
752			if h == nil {
753				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
754			}
755			e, _ := findEntry(h, itemID)
756			if e == nil {
757				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
758			}
759			if e.Status != EntryReturned {
760				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
761					ErrHandoverState, e.ItemID, e.Status.Label())
762			}
763			if len(e.Rounds) == 0 {
764				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
765			}
766			round := &e.Rounds[len(e.Rounds)-1]
767			if round.ResubmittedAt != nil {
768				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
769			}
770			now := svc.now()
771			round.Supplement = supplement
772			round.SupplementOperator = operator
773			round.SupplementAt = &now
774			round.ResubmittedAt = &now
775			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
776			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
777			e.Status = EntryPending
778			e.Operator = ""
779			e.ProcessedAt = nil
780			result = *h
781			return nil
782		})
783		return result, err
784	}
