811	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
812	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
813	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
814	// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
815	// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
816	// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
817	// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
818	// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
819	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
820	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
821	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
822	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
823	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
824	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
825	// 不改变事项、交接进度或班次结束时记录。
826	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
827		itemID = clean(itemID)
828		d := &svc.store.data
829		it, _ := findItem(d, itemID)
830		if it == nil {
831			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
832		}
833		j := ItemJourney{Item: *it}
834	
835		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
836		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
837		// 该轮重新提交、后续处理）。
838		type keyedEvent struct {
839			ev    JourneyEvent
840			group string // "" 表示事项自身事件，否则为交接编号
841			ord   int    // 同一（时刻、分组）内的先后
842		}
843		var events []keyedEvent
844		seq := 0
845		add := func(ev JourneyEvent, group string) {
846			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
847			seq++
848		}
849	
850		// received 事件与交接清单中的接收处理确属同一次接收时只展示一次（以交接
851		// 事件展示，信息更全：交接编号、交班与接班班次、该次保存的处理结果、操作人、
852		// 时间，继续跟踪还含跟踪说明与当时的后续负责人）。是否同一次接收不能仅凭
853		// 同一操作人与同一实际时刻：接收说明中明确记载的交接编号、交班、接班班次或
854		// 接收方式与本次交接不一致时，两条记录各自保留；说明没有明确记载（旧数据、
855		// 无对应交接清单的接收历史）时同样不合并，缺少足够信息无法确认即原样展示，
856		// 不凭班次负责人、事项当前位置或当前处理结果猜测归属，也不凭空补交接编号。
857		receivedUsed := make([]bool, len(it.Events))
858	
859		hs := append([]Handover(nil), d.Handovers...)
860		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
861		for k := range hs {
862			h := &hs[k]
863			e, _ := findEntry(h, itemID)
864			if e == nil {
865				continue
866			}
867			j.HasHandovers = true
868			j.Results = append(j.Results, EntryView{
869				HandoverID: h.ID,
870				FromShift:  h.FromShiftID,
871				ToShift:    h.ToShiftID,
872				Entry:      *e,
873			})
874	
875			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
876			add(JourneyEvent{
877				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
878				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
879			}, h.ID)
880			for _, r := range e.Rounds {
881				add(JourneyEvent{
882					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
883					Kind: "return", Operator: r.ReturnOperator,
884					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
885					RoundSeq: r.Seq, Reason: r.Reason,
886				}, h.ID)
887				if r.ResubmittedAt != nil {
888					add(JourneyEvent{
889						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
890						Kind: "resubmit", Operator: r.SupplementOperator,
891						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
892						RoundSeq: r.Seq, Supplement: r.Supplement,
893						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
894					}, h.ID)
895				}
896			}
897			if e.Status == EntryReturned && len(e.Rounds) == 0 {
898				// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
899				// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
900				// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
901				// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
902				// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
903				ev := JourneyEvent{
904					Kind: "return-incomplete", Operator: e.Operator,
905					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
906					HistoryIncomplete: true,
907				}
908				if validProcessedAt(e.ProcessedAt) {
909					ev.At, ev.TimeKnown = *e.ProcessedAt, true
910				}
911				add(ev, h.ID)
912			}
913			if e.Status.Received() {
914				kind := "confirm"
915				if e.Status == EntryTracking {
916					kind = "track"
917				}
918				ev := JourneyEvent{
919					Kind: kind, Operator: e.Operator,
920					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
921					TrackingNote: e.TrackingNote,
922					// 继续跟踪当时指定的后续负责人取自交接记录快照，
923					// 之后修改事项负责人不改变这里的历史值。
924					FollowOwner: e.FollowOwner,
925				}
926				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
927				// 时间标为未记录，排在有真实时间的事件之后。
928				if validProcessedAt(e.ProcessedAt) {
929					ev.At, ev.TimeKnown = *e.ProcessedAt, true
930				}
931				add(ev, h.ID)
932				if validProcessedAt(e.ProcessedAt) {
933					for i := range it.Events {
934						iev := &it.Events[i]
935						if iev.Kind != "received" || receivedUsed[i] {
936							continue
937						}
938						if !iev.At.Equal(*e.ProcessedAt) || iev.Operator != e.Operator {
939							continue
940						}
941						// 操作人与实际时刻相同只是前提；还要核对接收说明里明确记载的
942						// 交接编号、交班、接班班次与接收方式。只比较说明中明确记载的
943						// 字段（旧格式没有交接编号与交班班次）：记载与本次一致或未记载
944						// 才合并；明确不一致（交给另一个班次、方式不同、无对应交接
945						// 清单）时跳过这条，继续找真正同一次的记录——两条历史的存放
946						// 先后不能决定哪一条被隐藏。
947						attr, ok := parseReceivedDetail(iev.Detail)
948						if !ok {
949							continue
950						}
951						if (attr.handoverID != "" && attr.handoverID != h.ID) ||
952							(attr.fromShift != "" && attr.fromShift != h.FromShiftID) ||
953							(attr.toShift != "" && attr.toShift != h.ToShiftID) ||
954							(attr.kind != "" && attr.kind != kind) {
955							continue
956						}
957						receivedUsed[i] = true
958						break
959					}
960				}
961			}
962		}
963	
964		// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
965		// received 事件（旧数据）也保留。
966		for i, iev := range it.Events {
967			if iev.Kind == "received" && receivedUsed[i] {
968				continue
969			}
970			add(JourneyEvent{
971				At: iev.At, TimeKnown: !iev.At.IsZero(),
972				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
973			}, "")
974		}
975	
976		sort.SliceStable(events, func(i, k int) bool {
977			a, b := events[i], events[k]
978			if a.ev.TimeKnown != b.ev.TimeKnown {
979				return a.ev.TimeKnown
980			}
981			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
982				return a.ev.At.Before(b.ev.At)
983			}
984			if a.group != b.group {
985				return a.group < b.group
986			}
987			return a.ord < b.ord
988		})
989		for _, ke := range events {
990			j.Events = append(j.Events, ke.ev)
991		}
992		return j, nil
993	}
994	
995	// GetHandover 按编号查询交接。
996	func (svc *Service) GetHandover(id string) (Handover, error) {
997		h, _ := findHandover(&svc.store.data, clean(id))
998		if h == nil {
999			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
1000		}
1001		return *h, nil
1002	}
1003	
1004	// ListHandovers 返回全部交接记录，按编号排序。
1005	func (svc *Service) ListHandovers() []Handover {
1006		out := append([]Handover(nil), svc.store.data.Handovers...)
1007		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
1008		return out
1009	}
1010	
1011	// OverlapNotes 返回涉及指定班次的全部重叠说明。
1012	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
1013		shiftID = clean(shiftID)
1014		out := []OverlapNote{}
1015		for _, n := range svc.store.data.Notes {
1016			if n.ShiftA == shiftID || n.ShiftB == shiftID {
1017				out = append(out, n)
1018			}
1019		}
1020		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
1021		return out
1022	}
1023	
1024	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
1025	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
1026	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
1027	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
1028		shiftID = clean(shiftID)
1029		d := &svc.store.data
1030		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
1031		sh, _ := findShift(d, shiftID)
1032		if sh == nil {
1033			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
1034		}
1035		rep.Shift = *sh
1036	
1037		for _, n := range d.Notes {
1038			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
1039				rep.OverlapNotes = append(rep.OverlapNotes, n)
1040			}
1041		}
1042		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
1043	
1044		switch {
1045		case !sh.Closed:
1046			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
1047			rep.Items = currentItemsOfShift(d, sh.ID)
1048		case sh.CloseRecord != nil:
1049			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
1050			rep.ItemsAtClose = true
1051			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
1052			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
1053			for _, s := range rep.CloseItems {
1054				if it, _ := findItem(d, s.ItemID); it != nil {
1055					rep.LatestItems[s.ItemID] = *it
1056				}
1057			}
1058		default:
1059			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
1060			rep.HistoryIncomplete = true
1061			rep.Items = currentItemsOfShift(d, sh.ID)
1062		}
1063		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
1064	
1065		for i := range d.Handovers {
1066			h := &d.Handovers[i]
1067			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
1068			if !involved {
1069				continue
1070			}
1071			if h.FromShiftID == sh.ID {
1072				cp := *h
1073				rep.Outgoing = &cp
1074			}
1075			if h.ToShiftID == sh.ID {
1076				rep.Incoming = append(rep.Incoming, *h)
1077			}
1078			for j := range h.Entries {
1079				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
1080					HandoverID: h.ID,
1081					FromShift:  h.FromShiftID,
1082					ToShift:    h.ToShiftID,
1083					Entry:      h.Entries[j],
1084				})
1085			}
1086		}
1087		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
1088		for k := range rep.Results {
1089			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
1090		}
1091		return rep, nil
1092	}
1093

