package handover

import (
	"fmt"
	"os"
	"strings"
	"testing"
)

// 合并接收记录场景共用的旧数据：H001 由甲班 S001 交给乙班 S002，接班人李四
// 在 2026-10-02 11:00+08:00 选择继续跟踪；事项后来负责人已改为钱七，但交接
// 快照里当时的跟踪负责人仍是王五。事项历史除建立事件外，接收事件由用例注入。
// 另有一个丙班 S003（旧说明可能指向它，但不存在对应交接清单）。
func journeyMergeRaw(receivedEventsJSON, processedAtJSON string) string {
	return fmt.Sprintf(`{
  "shift_seq": 3, "item_seq": 1, "handover_seq": 1, "note_seq": 0,
  "shifts": [
    {"id":"S001","position":"调度","owner":"张三","start":"2026-10-02T08:00:00+08:00","end":"2026-10-02T16:00:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":true,"closed_at":"2026-10-02T16:00:00+08:00"},
    {"id":"S002","position":"调度","owner":"李四","start":"2026-10-02T16:00:00+08:00","end":"2026-10-02T23:00:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":false},
    {"id":"S003","position":"调度","owner":"赵六","start":"2026-10-02T16:00:00+08:00","end":"2026-10-02T23:30:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":true,"closed_at":"2026-10-02T23:30:00+08:00"}
  ],
  "items": [
    {"id":"I001","origin_shift_id":"S001","shift_ids":["S001","S002"],"current_shift_id":"S002",
     "content":"泵房压力异常","severity":"important","constraints":"夜间禁动","follow_owner":"钱七",
     "created_at":"2026-10-02T09:00:00+08:00",
     "events":[
       {"at":"2026-10-02T09:00:00+08:00","kind":"created","detail":"事项建立"}%s
     ]}
  ],
  "handovers": [
    {"id":"H001","position":"调度","from_shift_id":"S001","to_shift_id":"S002",
     "created_at":"2026-10-02T10:00:00+08:00","completed_at":%s,
     "entries":[
       {"item_id":"I001","content":"泵房压力异常","severity":"important","constraints":"夜间禁动",
        "follow_owner":"王五","status":"tracking","operator":"李四","processed_at":%s,
        "tracking_note":"每两小时记录压力"}
     ]}
  ],
  "notes": []
}`, receivedEventsJSON, processedAtJSON, processedAtJSON)
}

// 两类接收说明文本。
const (
	// 新版本格式：明确记载交接编号、两班与接收方式，与 H001 一致。
	canonicalTrackToB = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"交接 H001（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
	// 旧格式：同操作人同时刻，但明确记载交给丙班 S003、接收方式为确认接收；
	// 没有对应的交接清单，也不带任何交接编号。
	legacyConfirmToC = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"接班班次 S003 接收：确认接收"}`
	// 新格式，但两班与交接编号都对、接收方式却记载为确认接收。
	canonicalConfirmToB = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"交接 H001（S001 -> S002）接班班次接收：确认接收"}`
	// 没有任何明确归属信息的自由文本说明。
	freeTextReceive = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"当时口头打过招呼，先收下来"}`
	// 新格式但记载了另一个交接编号 H999（无此交接）。
	otherHandoverTrack = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"交接 H999（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
	// 旧版本格式，记载的接班班次与接收方式都与 H001 一致（无交接编号）。
	legacyTrackToB = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"接班班次 S002 接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
	// 新格式且与 H001 一致，但时间用另一时区表示同一实际时刻（11:00+08:00 == 10:00+07:00）。
	canonicalTrackToBTZ = `,{"at":"2026-10-02T10:00:00+07:00","kind":"received","operator":"李四","detail":"交接 H001（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
)

func countKind(events []JourneyEvent, kind string) int {
	n := 0
	for _, ev := range events {
		if ev.Kind == kind {
			n++
		}
	}
	return n
}

// TestItemJourneyMergeReceptionSameOperatorSameTime：操作人与实际时刻相同并不
// 足以判定同一次接收。交给丙班的旧确认接收说明必须完整保留，H001 交给乙班的
// 继续跟踪只展示一次；两条历史在事项事件里的存放先后不能决定哪一条被隐藏；
// 旧说明没有对应交接清单时，既不能丢掉它，也不能凭空补上交接编号。
func TestItemJourneyMergeReceptionSameOperatorSameTime(t *testing.T) {
	for _, order := range []struct{ name, events string }{
		{"旧丙班说明在前", legacyConfirmToC + canonicalTrackToB},
		{"旧丙班说明在后", canonicalTrackToB + legacyConfirmToC},
	} {
		t.Run(order.name, func(t *testing.T) {
			svc := openLegacyService(t, journeyMergeRaw(order.events, `"2026-10-02T11:00:00+08:00"`))
			j, err := svc.ItemJourney("I001")
			if err != nil {
				t.Fatalf("journey: %v", err)
			}
			if countKind(j.Events, "track") != 1 {
				t.Fatalf("交给乙班的继续跟踪应只展示一次：%v", journeyKinds(j))
			}
			if countKind(j.Events, "received") != 1 {
				t.Fatalf("交给丙班的旧确认接收说明应原样保留一条：%v", journeyKinds(j))
			}
			if countKind(j.Events, "confirm") != 0 {
				t.Fatalf("H001 中不存在确认接收事件，丙班说明不应被改写成交接确认：%v", journeyKinds(j))
			}
			var standalone *JourneyEvent
			for i := range j.Events {
				if j.Events[i].Kind == "received" {
					standalone = &j.Events[i]
				}
			}
			if standalone == nil || !strings.Contains(standalone.Detail, "接班班次 S003 接收：确认接收") {
				t.Fatalf("保留的应是交给丙班的原说明：%+v", standalone)
			}
			if standalone.HandoverID != "" || standalone.ToShift != "" {
				t.Fatalf("无交接清单的旧说明不能凭空补交接编号或接班班次字段：%+v", standalone)
			}

			text := FormatItemJourney(j)
			if !strings.Contains(text, "接班班次 S003 接收：确认接收") {
				t.Fatalf("展示应完整保留交给丙班的原说明：\n%s", text)
			}
			if strings.Count(text, "交接 H001（S001 -> S002）继续跟踪") != 1 {
				t.Fatalf("交给乙班的继续跟踪应只出现一次：\n%s", text)
			}
			if !strings.Contains(text, "跟踪说明=每两小时记录压力") ||
				!strings.Contains(text, "后续负责人=王五") {
				t.Fatalf("继续跟踪应带出当时的跟踪说明与后续负责人：\n%s", text)
			}
			// 事项后来修改的负责人只体现在开头最新状态，不替换当时记录。
			if !strings.Contains(text, "后续负责人：钱七") {
				t.Fatalf("查询开头仍应展示事项最新负责人钱七：\n%s", text)
			}
			if len(j.Results) != 1 || j.Results[0].HandoverID != "H001" ||
				j.Results[0].Entry.Status != EntryTracking {
				t.Fatalf("各次交接当前结果应保持不变：%+v", j.Results)
			}
		})
	}
}

// TestItemJourneyMergeReceptionDistinguishingFacts：记载的接收方式、交接编号
// 不同，或说明根本没有明确归属信息时，事项历史各自保留；记载一致（含旧版本
// 格式、不同时区表示同一时刻）时才合并为同一次接收。
func TestItemJourneyMergeReceptionDistinguishingFacts(t *testing.T) {
	cases := []struct {
		name           string
		events         string
		processedAt    string
		wantStandalone int // 期望保留的事项自身 received 事件条数
	}{
		{"记载接收方式不同", canonicalConfirmToB, `"2026-10-02T11:00:00+08:00"`, 1},
		{"说明无明确归属信息", freeTextReceive, `"2026-10-02T11:00:00+08:00"`, 1},
		{"记载另一个交接编号", otherHandoverTrack, `"2026-10-02T11:00:00+08:00"`, 1},
		{"旧格式记载一致应合并", legacyTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
		{"新格式记载一致应合并", canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
		{"不同时区同一时刻应合并", canonicalTrackToBTZ, `"2026-10-02T11:00:00+08:00"`, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			svc := openLegacyService(t, journeyMergeRaw(tc.events, tc.processedAt))
			j, err := svc.ItemJourney("I001")
			if err != nil {
				t.Fatalf("journey: %v", err)
			}
			if countKind(j.Events, "track") != 1 {
				t.Fatalf("H001 的继续跟踪应始终展示一次：%v", journeyKinds(j))
			}
			if got := countKind(j.Events, "received"); got != tc.wantStandalone {
				t.Fatalf("事项自身接收记录保留条数 want %d, got %d：%v", tc.wantStandalone, got, journeyKinds(j))
			}
		})
	}
}

// TestItemJourneyMergeReceptionDoesNotRewrite：单纯查询不改写任何历史、不移动
// 事项、不改变交接完成情况。
func TestItemJourneyMergeReceptionDoesNotRewrite(t *testing.T) {
	raw := journeyMergeRaw(legacyConfirmToC+canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`)
	svc := openLegacyService(t, raw)
	if _, err := svc.ItemJourney("I001"); err != nil {
		t.Fatalf("journey: %v", err)
	}
	// 重新打开同一文件，落盘内容必须与查询前逐字节一致。
	path := svc.store.Path()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	if string(b) != raw {
		t.Fatalf("单纯查询不应重写数据文件")
	}
	it, err := svc.GetItem("I001")
	if err != nil {
		t.Fatalf("get item: %v", err)
	}
	if it.CurrentShiftID != "S002" || it.FollowOwner != "钱七" {
		t.Fatalf("查询不应移动事项或替换负责人：%+v", it)
	}
	h, err := svc.GetHandover("H001")
	if err != nil || !h.Completed() {
		t.Fatalf("交接完成情况不应改变：%+v err=%v", h, err)
	}
}

package handover

import (
	"errors"
	"strings"
	"time"
)

// Severity 是事项的严重程度。
type Severity string

const (
	SeverityNormal    Severity = "normal"    // 普通
	SeverityImportant Severity = "important" // 重要
	SeverityUrgent    Severity = "urgent"    // 紧急
)

// ParseSeverity 解析严重程度，接受英文标识与中文名称；空串非法。
func ParseSeverity(s string) (Severity, error) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "normal", "普通":
		return SeverityNormal, nil
	case "important", "重要":
		return SeverityImportant, nil
	case "urgent", "紧急":
		return SeverityUrgent, nil
	}
	return "", errors.New("严重程度无效：必须是 normal(普通)、important(重要)、urgent(紧急) 之一")
}

func (v Severity) valid() bool {
	return v == SeverityNormal || v == SeverityImportant || v == SeverityUrgent
}

// Label 返回严重程度的中文展示名。
func (v Severity) Label() string {
	switch v {
	case SeverityNormal:
		return "普通"
	case SeverityImportant:
		return "重要"
	case SeverityUrgent:
		return "紧急"
	}
	return string(v)
}

// EntryStatus 是交接事项的当前处理结果。
type EntryStatus string

const (
	EntryPending   EntryStatus = "pending"   // 待处理
	EntryConfirmed EntryStatus = "confirmed" // 确认接收
	EntryTracking  EntryStatus = "tracking"  // 继续跟踪（已接收）
	EntryReturned  EntryStatus = "returned"  // 退回
)

// Label 返回交接结果的中文展示名。缺失或空结果显示“处理结果未记录”；
// 不属于现有四种结果的原值显示“处理结果无法识别”并带出保存的原值，
// 不推测成任何一种已知结果。
func (s EntryStatus) Label() string {
	switch s {
	case EntryPending:
		return "待处理"
	case EntryConfirmed:
		return "确认接收"
	case EntryTracking:
		return "继续跟踪"
	case EntryReturned:
		return "退回"
	case "":
		return "处理结果未记录"
	}
	return "处理结果无法识别（原值：" + string(s) + "）"
}

// Received 报告该结果是否表示接班班次已经接收。
func (s EntryStatus) Received() bool {
	return s == EntryConfirmed || s == EntryTracking
}

// EntryAction 是接班人对单项交接事项可执行的操作。
type EntryAction string

const (
	ActionConfirm EntryAction = "confirm" // 确认接收
	ActionReturn  EntryAction = "return"  // 退回
	ActionTrack   EntryAction = "track"   // 继续跟踪
)

// ParseAction 解析交接操作，接受英文标识与中文名称。
func ParseAction(s string) (EntryAction, error) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "confirm", "确认", "确认接收":
		return ActionConfirm, nil
	case "return", "退回":
		return ActionReturn, nil
	case "track", "tracking", "继续跟踪", "跟踪":
		return ActionTrack, nil
	}
	return "", errors.New("操作无效：必须是 confirm(确认接收)、return(退回)、track(继续跟踪) 之一")
}

// Shift 是一个岗位班次，编号全局稳定。
type Shift struct {
	ID        string     `json:"id"`
	Position  string     `json:"position"`
	Owner     string     `json:"owner"`
	Start     time.Time  `json:"start"`
	End       time.Time  `json:"end"`
	CreatedAt time.Time  `json:"created_at"`
	Closed    bool       `json:"closed"`
	ClosedAt  *time.Time `json:"closed_at,omitempty"`
	// CloseRecord 是班次成功结束时留下的事项记录，一经写定不再随事项的后续
	// 修改、关闭或流转而改变。nil 表示该班次结束时未留下记录（旧数据）。
	CloseRecord *ShiftCloseRecord `json:"close_record,omitempty"`
}

// CloseItemSnapshot 冻结班次结束时刻某一事项的内容、严重程度、限制条件、
// 后续负责人与关闭情况。结束前已关闭的事项保留关闭人与关闭时间；
// 结束时未关闭的事项，之后无论由哪一班关闭，都不改变这里的未关闭记录。
type CloseItemSnapshot struct {
	ItemID        string     `json:"item_id"`
	Content       string     `json:"content"`
	Severity      Severity   `json:"severity"`
	Constraints   string     `json:"constraints,omitempty"`
	FollowOwner   string     `json:"follow_owner"`
	Closed        bool       `json:"closed"`
	ClosedAt      *time.Time `json:"closed_at,omitempty"`
	CloseOperator string     `json:"close_operator,omitempty"`
}

// ShiftCloseRecord 是班次成功结束时在班全部事项的冻结清单。
// Items 包含该班新增与已经接收的事项，也保留结束前已关闭的事项；
// 尚未确认或被退回的交接事项不在其中（仍留在交接记录里）。
// 空切片表示结束时没有事项，与缺少历史记录（CloseRecord 为 nil）相区别。
type ShiftCloseRecord struct {
	Items []CloseItemSnapshot `json:"items"`
}

// ItemEvent 是事项的追加式历史事件。
type ItemEvent struct {
	At       time.Time `json:"at"`
	Kind     string    `json:"kind"`
	Operator string    `json:"operator,omitempty"`
	Detail   string    `json:"detail,omitempty"`
}

// Item 是一项未关闭事项。编号全局稳定，跨班次交接保持不变。
type Item struct {
	ID             string      `json:"id"`
	OriginShiftID  string      `json:"origin_shift_id"`
	ShiftIDs       []string    `json:"shift_ids"`
	CurrentShiftID string      `json:"current_shift_id"`
	Content        string      `json:"content"`
	Severity       Severity    `json:"severity"`
	Constraints    string      `json:"constraints,omitempty"`
	FollowOwner    string      `json:"follow_owner"`
	CreatedAt      time.Time   `json:"created_at"`
	Closed         bool        `json:"closed"`
	ClosedAt       *time.Time  `json:"closed_at,omitempty"`
	CloseOperator  string      `json:"close_operator,omitempty"`
	Events         []ItemEvent `json:"events"`
}

// ReturnRound 记录一次退回以及交班人随后的补充说明与重新提交。
// 原文与退回原因一经写入不再覆盖。
type ReturnRound struct {
	Seq                int        `json:"seq"`
	ReturnedAt         time.Time  `json:"returned_at"`
	ReturnOperator     string     `json:"return_operator"`
	Reason             string     `json:"reason"`
	Supplement         string     `json:"supplement,omitempty"`
	SupplementOperator string     `json:"supplement_operator,omitempty"`
	SupplementAt       *time.Time `json:"supplement_at,omitempty"`
	ResubmittedAt      *time.Time `json:"resubmitted_at,omitempty"`
}

// HandoverEntry 是交接清单中的单项处理记录。
type HandoverEntry struct {
	ItemID       string        `json:"item_id"`
	Content      string        `json:"content"`
	Severity     Severity      `json:"severity"`
	Constraints  string        `json:"constraints,omitempty"`
	FollowOwner  string        `json:"follow_owner"`
	Status       EntryStatus   `json:"status"`
	Operator     string        `json:"operator,omitempty"`
	ProcessedAt  *time.Time    `json:"processed_at,omitempty"`
	TrackingNote string        `json:"tracking_note,omitempty"`
	Rounds       []ReturnRound `json:"rounds,omitempty"`
}

// Handover 是一个交班班次对接班班次发起的一次交接。
type Handover struct {
	ID          string    `json:"id"`
	Position    string    `json:"position"`
	FromShiftID string    `json:"from_shift_id"`
	ToShiftID   string    `json:"to_shift_id"`
	CreatedAt   time.Time `json:"created_at"`
	// CompletedAt 是整份交接真正接收齐全部事项的时刻。空清单在发起时即完成；
	// 非空清单在最后一项被确认接收或继续跟踪、整份交接首次全部明确接收时，
	// 以那次成功处理的时间为准。旧数据若在清单仍有结果缺失、无法识别、待处理
	// 或退回项时误写过完成时间（或只留下零值），接班人逐项补齐、最后一项成功
	// 接收时用本次处理时间覆盖旧时间，不沿用补齐前的时刻。单纯查询、补充后
	// 重新提交与重复发起都不更新它，也不为已全部接收但缺少完成时间的旧记录
	// 编造时刻。
	CompletedAt *time.Time      `json:"completed_at,omitempty"`
	Entries     []HandoverEntry `json:"entries"`
}

// Completed 报告交接是否已完成。完成以清单里每一项都明确为确认接收或
// 继续跟踪为准：待处理、退回、结果缺失（空）或无法识别都使交接保持未完成，
// 其他项全部已接收也不能抵消不确定项；空清单直接完成。判定只看清单中保存的
// 处理结果，不以已完成时间、事项所在班次、处理人或退回历史推测接收。
func (h *Handover) Completed() bool {
	for i := range h.Entries {
		if !h.Entries[i].Status.Received() {
			return false
		}
	}
	return true
}

// OverlapNote 记录同一岗位两个重叠班次的重叠说明。
type OverlapNote struct {
	ID        string    `json:"id"`
	Position  string    `json:"position"`
	ShiftA    string    `json:"shift_a"`
	ShiftB    string    `json:"shift_b"`
	Note      string    `json:"note"`
	CreatedAt time.Time `json:"created_at"`
}

// JourneyEvent 是事项处理经过中的一条记录：可能来自事项自身历史
// （建立/修改/关闭/接收），也可能来自它参与的交接（发起交接、逐轮退回、
// 补充后重新提交、确认接收、继续跟踪）。交接相关事件带有交接编号与交班、
// 接班班次；Operator 为空表示该操作人未记录（旧数据可能缺人名）。
type JourneyEvent struct {
	At                 time.Time  // 实际发生时刻；TimeKnown 为 false 表示未记录
	TimeKnown          bool       // At 是否有效（旧数据可能缺时间）
	Kind               string     // created/updated/closed/received/handover-init/return/return-incomplete/resubmit/confirm/track
	Operator           string     // 实际操作人；空表示未记录
	Detail             string     // 事项自身事件附带的说明
	// HistoryIncomplete 表示该事件由当前保存的处理结果推断而来（当前结果是退回
	// 却没有任何退回轮次记录）：退回确实发生过，但原因与轮次详情没有可靠记录，
	// 只展示当前保存的处理人与处理时间，并明确提示退回历史不完整。
	HistoryIncomplete bool
	HandoverID        string // 交接相关事件所属的交接编号
	FromShift          string     // 交班班次
	ToShift            string     // 接班班次
	RoundSeq           int        // 退回/重新提交的轮次
	Reason             string     // 该轮完整退回原因
	Supplement         string     // 该轮补充说明
	SupplementOperator string     // 补充人
	SupplementAt       *time.Time // 补充时间
	TrackingNote       string     // 继续跟踪的跟踪说明
	FollowOwner        string     // 继续跟踪当时指定的后续负责人（不随后续修改改变）
}

// ItemJourney 是凭事项编号查询得到的完整处理经过：开头为事项最新状态，
// Events 是合并事项自身历史与各次交接经过后的时间线，Results 是该事项在
// 每次交接中的当前处理结果。
type ItemJourney struct {
	Item         Item
	Events       []JourneyEvent // 按实际发生时刻排序（不同时区按同一实际时刻比较）
	Results      []EntryView    // 按交接编号排列
	HasHandovers bool           // false 表示尚未参与交接
}

// EntryView 把交接单项与其所属交接编号关联，用于按班次查询。
type EntryView struct {
	HandoverID string
	FromShift  string
	ToShift    string
	Entry      HandoverEntry
}

// ShiftReport 是按班次查询得到的完整视图。
type ShiftReport struct {
	Shift        Shift
	OverlapNotes []OverlapNote
	// Items 是进行中班次的当前事项，或旧数据班次（无结束时记录）的当前事项。
	Items []Item
	// CloseItems 是已结束班次结束时刻的事项快照（已冻结），按事项编号排列。
	CloseItems []CloseItemSnapshot
	// ItemsAtClose 为 true 表示本次查到了结束时记录，CloseItems 即结束时事实。
	ItemsAtClose bool
	// HistoryIncomplete 为 true 表示该已结束班次是旧数据、缺少结束时记录，
	// Items 只是当前信息，不能视为结束时事实。
	HistoryIncomplete bool
	// LatestItems 按事项编号索引结束时事项的最新状态，与结束时信息对照。
	LatestItems map[string]Item
	Outgoing    *Handover
	Incoming    []Handover
	// Results 按事项编号汇总它在历次交接中的当前结果与退回历史。
	Results map[string][]EntryView
}

